'use client';

import {
  Bars3Icon,
  BellIcon,
  SunIcon,
  MoonIcon,
  CheckCircleIcon,
  ClockIcon,
  TrashIcon
} from '@heroicons/react/24/outline';
import { useState, useEffect } from 'react';
import { useTheme } from '@/hooks/use-theme';
import { useNotifications } from '@/hooks/use-notifications';
import { Button } from '@/components/ui/button';
import { formatDate } from '@/lib/utils';

interface HeaderProps {
  onMenuClick: () => void;
}

export default function Header({ onMenuClick }: HeaderProps) {
  const [showNotifications, setShowNotifications] = useState(false);
  const { theme, toggleTheme } = useTheme();
  const { notifications, unreadCount, markAsRead, markAllAsRead, clearAll } = useNotifications();
  const [userProfile, setUserProfile] = useState({ firstName: 'Admin', lastName: 'User', email: 'admin@pos.com' });

  useEffect(() => {
    const saved = localStorage.getItem('settings_profile');
    if (saved) setUserProfile(JSON.parse(saved));
  }, []);

  return (
    <header className="bg-card border-b border-divider sticky top-0 z-30">
      <div className="flex items-center justify-between h-16 px-4 sm:px-6">
        {/* Mobile menu button */}
        <button
          onClick={onMenuClick}
          className="p-2 rounded-lg text-text-secondary hover:text-primary hover:bg-surface transition-colors lg:hidden"
        >
          <Bars3Icon className="h-6 w-6" />
        </button>

        {/* Page Title */}
        <div className="flex-1 min-w-0 ml-2 lg:ml-0">
          <h1 className="text-lg sm:text-xl font-black text-primary tracking-tight truncate">EcoTracker Admin</h1>
        </div>

        {/* Right side actions */}
        <div className="flex items-center space-x-1 sm:space-x-2">
          {/* Theme Toggle */}
          <button
            onClick={toggleTheme}
            className="p-2 sm:p-2.5 rounded-xl text-text-secondary hover:text-primary hover:bg-surface transition-all active:scale-95 group"
            title="Toggle theme"
          >
            {theme === 'dark' ? (
              <SunIcon className="h-5 w-5 transition-transform group-hover:rotate-45" />
            ) : (
              <MoonIcon className="h-5 w-5 transition-transform group-hover:-rotate-12" />
            )}
          </button>

          {/* Notifications */}
          <div className="relative">
            <button
              onClick={() => setShowNotifications(!showNotifications)}
              className="p-2 sm:p-2.5 rounded-xl text-text-secondary hover:text-primary hover:bg-surface transition-all active:scale-95 relative group"
            >
              <BellIcon className="h-6 w-6 transition-transform group-hover:rotate-12" />
              {unreadCount > 0 && (
                <span className="absolute top-2 right-2 h-4 w-4 bg-error text-[10px] font-bold text-white rounded-full flex items-center justify-center border-2 border-card animate-pulse">
                  {unreadCount}
                </span>
              )}
            </button>

            {showNotifications && (
              <>
                <div
                  className="fixed inset-0 z-40"
                  onClick={() => setShowNotifications(false)}
                />
                <div className="absolute right-0 mt-3 w-96 bg-card rounded-2xl shadow-2xl border border-divider z-50 overflow-hidden animate-in fade-in zoom-in-95 duration-200 origin-top-right">
                  <div className="p-4 bg-surface/50 border-b border-divider flex items-center justify-between">
                    <div>
                      <h3 className="font-black text-primary">Notifications</h3>
                      <p className="text-[10px] text-text-secondary uppercase tracking-widest font-bold">Latest Alerts</p>
                    </div>
                    <div className="flex gap-2">
                      <Button variant="ghost" size="sm" className="h-7 text-[10px] px-2 font-bold" onClick={markAllAsRead}>Mark all read</Button>
                      <Button variant="ghost" size="sm" className="h-7 text-[10px] px-2 font-bold text-error hover:bg-error/5" onClick={clearAll}>Clear</Button>
                    </div>
                  </div>

                  <div className="max-h-[450px] overflow-y-auto custom-scrollbar">
                    {notifications.length === 0 ? (
                      <div className="p-8 text-center italic text-text-secondary text-sm">
                        No notifications found
                      </div>
                    ) : (
                      notifications.map((n) => (
                        <div
                          key={n.id}
                          onClick={() => markAsRead(n.id)}
                          className={`p-4 border-b border-divider hover:bg-surface transition-colors cursor-pointer relative group ${!n.isRead ? 'bg-primary/5' : ''}`}
                        >
                          <div className="flex items-start gap-3">
                            <div className={`mt-1 h-2 w-2 rounded-full flex-shrink-0 ${n.type === 'error' ? 'bg-error' :
                                n.type === 'warning' ? 'bg-warning' :
                                  n.type === 'success' ? 'bg-success' : 'bg-primary'
                              } ${!n.isRead ? 'animate-pulse' : 'opacity-40'}`} />
                            <div className="space-y-1 pr-4">
                              <p className={`text-sm font-bold ${!n.isRead ? 'text-primary' : 'text-text-secondary'}`}>{n.title}</p>
                              <p className="text-xs text-text-secondary leading-relaxed">{n.message}</p>
                              <div className="flex items-center gap-2 pt-1 opacity-60">
                                <ClockIcon className="h-3 w-3" />
                                <span className="text-[10px] font-medium">{formatDate(n.timestamp)}</span>
                              </div>
                            </div>
                          </div>
                        </div>
                      ))
                    )}
                  </div>
                </div>
              </>
            )}
          </div>

          <div className="h-8 w-px bg-divider mx-2" />

          {/* User profile */}
          <div className="flex items-center gap-3 pl-2 group cursor-pointer">
            <div className="text-right hidden sm:block">
              <p className="text-sm font-black text-primary group-hover:text-primary-light transition-colors">{userProfile.firstName} {userProfile.lastName}</p>
              <p className="text-[10px] text-text-secondary font-bold uppercase tracking-tighter">System Administrator</p>
            </div>
            <div className="h-10 w-10 bg-primary/10 border-2 border-primary/20 rounded-xl flex items-center justify-center shadow-lg group-hover:scale-105 transition-all">
              <span className="text-sm font-black text-primary">
                {userProfile.firstName[0]}{userProfile.lastName[0]}
              </span>
            </div>
          </div>
        </div>
      </div>
    </header>
  );
}
